$check('third_person_is_not_followup',ChiefOperations::kind('Ella dijo que todos los días revisar el correo')===null);
$seed();$r=$run('Jeison, muchísimas gracias. Estás haciendo una gran labor muy importante siempre compartir al grupo del equipo jurídico.');$check('thanks_routing_no_clarify',str_contains($r['reply'],'Gracias, Sandra.')&&!str_contains($r['reply'],'?'));
$seed();$r=$run('Lo que necesito es que tú aprendas demasiado. Quiero que tengas total conocimiento de cómo funciona el derecho que aprendas demasiado de cada uno de los documentos que recibes');$check('learning_followup_answered',$r['reason']==='OPERATIONAL_REQUEST'&&str_contains($r['reply'],'por partes'));
$check('no_legal_policy_from_learning_request',str_contains($r['reply'],'no las tomaré como reglas'));
